def _run_git(args, cwd):
    proc = subprocess.run(["git", *args], cwd=cwd, text=True, capture_output=True)
    if proc.returncode != 0: raise RuntimeError(proc.stderr.strip() or proc.stdout.strip())
    return proc.stdout.strip()

