def _problem_tags(tags=None):
    "Return normalized problem-memory tags."
    if tags is None: return []
    parts = re.split(r"[,\n]+", tags) if isinstance(tags, str) else list(tags)
    return sorted({str(tag).strip().lower() for tag in parts if str(tag).strip()})


def _problem_project(project="."):
    "Return a stable project label for problem memory rows."
    try: return str(Path(project or ".").expanduser().resolve())
    except Exception: return str(project or ".")


def _problem_text(problem, solution, task="", evidence="", tags=None):
    "Build searchable text for a problem-solution statement."
    tag_list = _problem_tags(tags)
    chunks = [f"Problem: {problem}", f"Solution: {solution}"]
    if task: chunks.append(f"Task: {task}")
    if evidence: chunks.append(f"Evidence: {evidence}")
    if tag_list: chunks.append("Tags: " + ", ".join(tag_list))
    return "\n".join(chunks)


def _problem_key(problem, solution):
    "Return the dedupe key and normalized problem text."
    problem = " ".join(str(problem or "").split())
    solution = " ".join(str(solution or "").split())
    if not problem or not solution: raise ValueError("problem and solution are required")
    return _stable_item_id("problem_statement", problem.lower(), solution.lower()), problem, solution


def _problem_row(problem, solution, task="", project=".", evidence="", outcome="applied", tags=None):
    "Create one problem-memory row before embedding."
    item_id, problem, solution = _problem_key(problem, solution)
    now = time.time()
    tag_list = _problem_tags(tags)
    return {
        "item_id": item_id,
        "kind": "problem_statement",
        "problem": problem,
        "solution": solution,
        "task": str(task or ""),
        "project": _problem_project(project),
        "evidence": str(evidence or ""),
        "outcome": str(outcome or "applied"),
        "tags": tag_list,
        "search_text": _problem_text(problem, solution, task=task, evidence=evidence, tags=tag_list),
        "observed_count": 1,
        "created_at": now,
        "last_seen": now,
    }


def _merge_problem_row(existing, incoming):
    "Merge a repeated problem-solution observation into an existing row."
    merged = dict(existing)
    old_search = merged.get("search_text")
    for key in ("task", "project", "evidence", "outcome"):
        if incoming.get(key): merged[key] = incoming[key]
    merged["tags"] = sorted({*_problem_tags(merged.get("tags")), *_problem_tags(incoming.get("tags"))})
    merged["observed_count"] = int(merged.get("observed_count") or 0) + 1
    merged["last_seen"] = incoming["last_seen"]
    merged["search_text"] = _problem_text(
        merged.get("problem", ""), merged.get("solution", ""),
        task=merged.get("task", ""), evidence=merged.get("evidence", ""), tags=merged.get("tags"),
    )
    if merged["search_text"] != old_search:
        merged.pop("vector", None)
        merged.pop("embedding_backend", None)
    return merged


def problem_statement_add(
    problem: str,  # Reusable problem statement
    solution: str,  # Reusable solution statement
    task: str = "",  # Task where this pair was observed
    project: str = ".",  # Project path or label
    evidence: str = "",  # Short evidence that the solution worked
    outcome: str = "applied",  # applied, partial, failed, skipped, etc.
    tags=None,  # Optional tags as a list or comma-separated string
    path: str | None = None,  # Override reference home
):
    "Store or update one reusable problem-solution statement."
    incoming = _problem_row(problem, solution, task=task, project=project, evidence=evidence, outcome=outcome, tags=tags)
    rows, updated = [], incoming
    replaced = False
    for row in _lance_rows(path, "problems"):
        if row.get("item_id") == incoming["item_id"]:
            updated = _merge_problem_row(row, incoming)
            rows.append(updated)
            replaced = True
        else:
            rows.append(row)
    if not replaced: rows.append(incoming)
    _write_lance_table(path, "problems", rows)
    return {"item_id": updated["item_id"], "created": not replaced, "row": updated}


def _problem_score(row, query):
    "Score a stored problem against a new query."
    query_tokens = set(_query_tokens(query))
    row_tokens = set(_query_tokens(row.get("search_text", "")))
    tag_hits = query_tokens & set(_problem_tags(row.get("tags")))
    try: observed = int(row.get("observed_count") or 0)
    except (TypeError, ValueError): observed = 0
    vector_score = 0.0
    try: vector_score = max(0.0, 1.0 - float(row.get("_distance", 1.0))) * 8
    except (TypeError, ValueError): pass
    return round(vector_score + len(query_tokens & row_tokens) + 2 * len(tag_hits) + min(observed, 5) * 0.2, 6)


def _problem_hit(row, query):
    "Return the public problem-memory hit shape."
    return {
        "item_id": row.get("item_id"),
        "problem": row.get("problem", ""),
        "solution": row.get("solution", ""),
        "task": row.get("task", ""),
        "project": row.get("project", ""),
        "evidence": row.get("evidence", ""),
        "outcome": row.get("outcome", ""),
        "tags": _problem_tags(row.get("tags")),
        "observed_count": int(row.get("observed_count") or 0),
        "score": _problem_score(row, query),
        "search_sources": row.get("search_sources") or [],
    }


def _problem_candidates(query, path=None, candidate_k=50):
    "Return vector/FTS candidates with lexical fallback."
    table = _reference_table(path, "problems")
    rows = _lance_rows(path, "problems")
    if table is None or not rows: return rows, "lancedb", None
    dims = next((len(row.get("vector") or []) for row in rows if row.get("vector")), None)
    text_query = " ".join(_query_tokens(query)) or query
    vector_rows, note = [], None
    if dims:
        try: vector_rows = _search_rows(table.search(_reference_vector(query, dims=dims)).metric("cosine"), candidate_k)
        except Exception as exc: note = f"vector search unavailable: {type(exc).__name__}: {exc}"
    else:
        note = "problem memory stored without vectors; lexical scoring only"
    try: fts_rows = _search_rows(table.search(text_query, query_type="fts"), candidate_k)
    except Exception: fts_rows = []
    merged = _merge_lancedb_rows(("vector", vector_rows), ("bm25_fts", fts_rows))
    backend = "lancedb_bm25_vector" if vector_rows else "lancedb_lexical"
    return (merged or rows), backend, note or _reference_embedding_note()


def _problem_context_markdown(hits):
    "Render compact problem-memory context for an agent prompt."
    if not hits: return "No similar problem memories found."
    lines = ["Similar problem memories:"]
    for hit in hits:
        tags = ", ".join(hit.get("tags") or [])
        suffix = f" tags={tags}" if tags else ""
        lines.append(f"- Problem: {hit['problem']} Solution: {hit['solution']}{suffix}")
    return "\n".join(lines)


def problem_statement_query(
    query: str,  # New problem or task to compare against stored memories
    top_k: int = 5,  # Number of memories to return
    project: str | None = None,  # Optional project filter
    path: str | None = None,  # Override reference home
):
    "Find reusable problem-solution statements for a new task."
    top_k = _clamp_int(top_k, 5, 1, _REFERENCE_MAX_TOP_K, "top_k")
    rows, backend, note = _problem_candidates(query, path=path, candidate_k=top_k * 20)
    if project is not None:
        project_label = _problem_project(project)
        rows = [row for row in rows if row.get("project") == project_label]
    hits = [_problem_hit(row, query) for row in rows]
    hits = sorted(hits, key=lambda hit: hit["score"], reverse=True)[:top_k]
    return {"query": query, "backend": backend, "note": note, "count": len(hits), "context": _problem_context_markdown(hits), "hits": hits}


def problem_statement_list(path: str | None = None, limit: int = 20):
    "List recent reusable problem-solution statements."
    limit = _clamp_int(limit, 20, 1, 200, "limit")
    rows = sorted(_lance_rows(path, "problems"), key=lambda row: row.get("last_seen") or 0, reverse=True)[:limit]
    return {"count": len(rows), "hits": [_problem_hit(row, row.get("search_text", "")) for row in rows]}

